func _enter_tree() -> void :
	if not OS.has_feature("web"):
		return
	var runner_seed: Variant = JavaScriptBridge.eval(
		"typeof window.__getRandomSeed === 'function' ? window.__getRandomSeed() : null", 
		true
	)
	if typeof(runner_seed) == TYPE_INT or typeof(runner_seed) == TYPE_FLOAT:
		seed(int(runner_seed))

var task_id: String = JavaScriptBridge.eval("window.__aboutTimeTaskId || ''", true)
if task_id == "430_01":
	$Buttons / Buttons / ButtonTutorial.call_deferred("_on_pressed")
elif task_id in ["430_02", "430_03", "430_04", "430_05", "430_06"]:
	$Buttons / Buttons / PlayButton.call_deferred("_on_pressed")

func _publish_policy_observation() -> void :
	var scene: Node = get_tree().current_scene
	if scene == null:
		return
	var viewport_size: Vector2 = get_viewport().get_visible_rect().size
	var viewport_rect: Rect2 = Rect2(Vector2.ZERO, viewport_size)
	var controls: Array = []
	var blocker: Node = _policy_find(scene, "MouseStopper")
	var input_blocked: bool = blocker != null and blocker is CanvasItem and (blocker as CanvasItem).is_visible_in_tree()
	_policy_collect_controls(scene, controls, viewport_rect, input_blocked)
	var tutorial_state: Variant = _policy_tutorial_text(scene, viewport_rect)
	var snapshot: Dictionary = {
		"screen_phase": _policy_screen_phase(scene, viewport_rect, tutorial_state, input_blocked), 
		"active_controls": controls, 
		"clock_readouts": _policy_clock_readouts(scene), 
		"tutorial_text_state": tutorial_state, 
		"visible_shop_edit_state": _policy_shop_edit_state(scene, viewport_rect), 
		"_viewport_size": [viewport_size.x, viewport_size.y]
	}
	JavaScriptBridge.eval("window.__setAboutTimePolicyObservation(" + JSON.stringify(snapshot) + ")", true)


func _policy_find(root: Node, node_name: String) -> Node:
	if root == null:
		return null
	return root.find_child(node_name, true, false)


func _policy_bool(value: Variant) -> bool:
	return value is bool and value


func _policy_script_path(node: Node) -> String:
	if node == null:
		return ""
	var script_resource: Variant = node.get_script()
	if script_resource is Script:
		return script_resource.resource_path
	return ""


func _policy_collect_script_nodes(root: Node, suffix: String, output: Array) -> void :
	if root == null:
		return
	if _policy_script_path(root).ends_with(suffix):
		output.append(root)
	for child in root.get_children():
		_policy_collect_script_nodes(child, suffix, output)


func _policy_visible_on_screen(node: Node, viewport_rect: Rect2) -> bool:
	if not node is Control:
		return false
	var control: Control = node as Control
	if not control.is_visible_in_tree():
		return false
	var rect: Rect2 = control.get_global_rect()
	return rect.size.x > 0.5 and rect.size.y > 0.5 and rect.intersects(viewport_rect)


func _policy_screen_content(root: Node) -> Node:
	if root == null:
		return null
	if root.name == "ClockChanging":
		return root.get_node_or_null("SkipButton")
	var panel: Node = root.get_node_or_null("Panel")
	return panel if panel != null else root


func _policy_screen_content_visible(root: Node, viewport_rect: Rect2) -> bool:
	return _policy_visible_on_screen(_policy_screen_content(root), viewport_rect)


func _policy_screen_transition_settled(root: Node, viewport_rect: Rect2, open_state: Variant = null) -> bool:
	if root == null or not root is Control:
		return true
	if not _policy_screen_content_visible(root, viewport_rect):
		return true
	var control: Control = root as Control
	var open_target: Vector2 = Vector2.ZERO
	var closed_target: Vector2 = Vector2(0.0, control.size.y)
	if open_state is bool:
		var target: Vector2 = open_target if open_state else closed_target
		return control.position.distance_to(target) <= 1.0
	return minf(control.position.distance_to(open_target), control.position.distance_to(closed_target)) <= 1.0


func _policy_text_from_control(node: Node) -> String:
	if node is RichTextLabel:
		return (node as RichTextLabel).get_parsed_text().strip_edges()
	if node is Label:
		return (node as Label).text.strip_edges()
	return ""


func _policy_display_text(node: Node, viewport_rect: Rect2) -> String:
	if node == null:
		return ""
	if node is Button and !(node as Button).text.strip_edges().is_empty():
		return (node as Button).text.strip_edges()
	for child_name in ["Text", "Label"]:
		var label: Node = node.find_child(child_name, true, false)
		if label != null and _policy_visible_on_screen(label, viewport_rect):
			var text: String = _policy_text_from_control(label)
			if !text.is_empty():
				return text
	return ""


func _policy_button_action(button: BaseButton) -> String:
	var script_path: String = _policy_script_path(button)
	if button.name == "PassTime":
		return "forward_time"
	if button.name == "EndShift":
		return "finish_shift"
	if button.name == "PlayButton":
		return "play"
	if button.name == "Use":
		return "use_paper"
	if button.name == "SkipButton":
		return "skip_clock_edit"
	if button.name == "Buy":
		return "buy_item"
	if script_path.ends_with("/changeable_clock_number.gd"):
		return "select_clock_number"
	if script_path.ends_with("/Objs/Papers/paper.gd"):
		return "select_paper"
	if script_path.ends_with("/Objs/Papers/box_of_papers.gd"):
		return "select_paper_box"
	if script_path.ends_with("/Objs/Gears/gear.gd"):
		return "select_gear"
	if script_path.ends_with("/Objs/Gears/usable_gear.gd"):
		return "gear_slot"
	return "press_button"


func _policy_button_selected(button: BaseButton) -> bool:
	var script_path: String = _policy_script_path(button)
	if script_path.ends_with("/Objs/Gears/gear.gd") or script_path.ends_with("/Objs/Papers/box_of_papers.gd") or script_path.ends_with("/Objs/Papers/paper.gd"):
		return _policy_bool(button.get("active"))
	return button.button_pressed


func _policy_collect_controls(root: Node, output: Array, viewport_rect: Rect2, input_blocked: bool) -> void :
	if root is BaseButton:
		var button: BaseButton = root as BaseButton
		if button.name != "InvisibleButton" and _policy_visible_on_screen(button, viewport_rect):
			var label: String = _policy_display_text(button, viewport_rect)
			var action: String = _policy_button_action(button)
			var rect: Rect2 = button.get_global_rect()
			if action == "select_clock_number":
				rect = _policy_transformed_rect(button)
			if label.is_empty():
				label = action
			output.append({
				"id": str(button.get_path()), 
				"label": label, 
				"action": action, 
				"enabled": !button.disabled and button.mouse_filter != Control.MOUSE_FILTER_IGNORE and !input_blocked, 
				"selected": _policy_button_selected(button), 
				"bbox": {"x": rect.position.x, "y": rect.position.y, "width": rect.size.x, "height": rect.size.y}
			})
	for child in root.get_children():
		_policy_collect_controls(child, output, viewport_rect, input_blocked)


func _policy_transformed_rect(control: Control) -> Rect2:
	var transform: Transform2D = control.get_global_transform_with_canvas()
	var points: Array[Vector2] = [
		transform * Vector2.ZERO, 
		transform * Vector2(control.size.x, 0.0), 
		transform * control.size, 
		transform * Vector2(0.0, control.size.y)
	]
	var minimum: Vector2 = points[0]
	var maximum: Vector2 = points[0]
	for point in points:
		minimum.x = minf(minimum.x, point.x)
		minimum.y = minf(minimum.y, point.y)
		maximum.x = maxf(maximum.x, point.x)
		maximum.y = maxf(maximum.y, point.y)
	return Rect2(minimum, maximum - minimum)


func _policy_tutorial_text(scene: Node, viewport_rect: Rect2) -> Variant:
	var cutscene: Node = _policy_find(scene, "Cutscene")
	if cutscene != null and _policy_visible_on_screen(cutscene, viewport_rect):
		var label: Node = cutscene.find_child("Label", true, false)
		var text: String = _policy_text_from_control(label)
		var visible_count: int = int(label.get("visible_characters")) if label != null else 0
		if visible_count < 0:
			visible_count = text.length()
		var visible_text: String = text.substr(0, min(visible_count, text.length()))
		var tween: Variant = cutscene.get("current_tween")
		return {"kind": "dialogue", "text": visible_text, "reveal_complete": visible_count >= text.length() and (tween == null or !tween.is_running())}
	var overlay: Node = _policy_find(scene, "Tutorial Overlay")
	if overlay != null and _policy_visible_on_screen(overlay, viewport_rect) and int(overlay.get("current")) > 0:
		var index: int = int(overlay.get("current")) - 1
		if index >= 0 and index < overlay.get_child_count():
			var callout: Node = overlay.get_child(index)
			var panel: Node = callout.find_child("PanelContainer", true, false)
			var label: Node = panel.get_child(0) if panel != null and panel.get_child_count() > 0 else null
			var text: String = _policy_text_from_control(label)
			var visible_count: int = int(label.get("visible_characters")) if label != null else 0
			if visible_count < 0:
				visible_count = text.length()
			var visible_text: String = text.substr(0, min(visible_count, text.length()))
			var tween: Variant = overlay.get("current_tween")
			return {"kind": "callout", "text": visible_text, "reveal_complete": visible_count >= text.length() and (tween == null or !tween.is_running())}
	return null


func _policy_clock_animation_settled(scene: Node, round_score: Node, current_score: Node, game_node: Node) -> bool:
	if game_node != null and _policy_bool(game_node.get("playing")):
		return false
	if round_score != null and absf(float(round_score.get("lerpval")) - float(round_score.get("val"))) > 0.11:
		return false
	if current_score != null and (_policy_bool(current_score.get("multiplying")) or _policy_bool(current_score.get("finishing"))):
		return false
	var clock: Node = _policy_find(game_node, "Clock") if game_node != null else null
	var pointers: Node = _policy_find(clock, "Pointers") if clock != null else null
	if pointers != null:
		for pointer in pointers.get_children():
			var target_angle: float = float(pointer.get("angle"))
			if absf(wrapf(float(pointer.rotation) - target_angle, - PI, PI)) > 0.02:
				return false
	var spin_labels: Array = []
	_policy_collect_script_nodes(scene, "/Scenes/SpinLabel.gd", spin_labels)
	for label in spin_labels:
		if _policy_visible_on_screen(label, get_viewport().get_visible_rect()):
			if absf(float(label.rotation_degrees)) > 0.1 or absf(float(label.scale.x) - 1.0) > 0.01 or absf(float(label.scale.y) - 1.0) > 0.01:
				return false
	return true


func _policy_clock_readouts(scene: Node) -> Variant:
	var stats: Node = _policy_find(scene, "Stats&Items")
	var minimum: Node = _policy_find(stats, "MinScore") if stats != null else null
	var score: Node = _policy_find(stats, "RoundScore") if stats != null else null
	var current: Node = _policy_find(stats, "CurentScore") if stats != null else null
	var plays: Node = _policy_find(stats, "Plays") if stats != null else null
	var game_node: Node = _policy_find(scene, "Game")
	if minimum == null or score == null or plays == null:
		return null
	return {
		"round_number": int(minimum.get("rounds")), 
		"round_score_points": float(score.get("val")), 
		"minimum_score_points": float(minimum.get("min_score")), 
		"forwards_remaining": int(plays.get("plays_left")), 
		"animation_settled": _policy_clock_animation_settled(scene, score, current, game_node)
	}


func _policy_visible_description(item: Node, viewport_rect: Rect2) -> Variant:
	var description: Node = item.find_child("Description", true, false)
	if description == null or not description is Control:
		return null
	var panel: Control = description as Control
	if panel.scale.x < 0.9 or panel.scale.y < 0.9 or not _policy_visible_on_screen(panel, viewport_rect):
		return null
	var label: Node = panel.find_child("Label", true, false)
	if label == null or not _policy_visible_on_screen(label, viewport_rect):
		return null
	return _policy_text_from_control(label)


func _policy_item_name(item: Node) -> String:
	var resource: Variant = item.get("res")
	if resource != null:
		var value: Variant = resource.get("Name")
		if value != null:
			return str(value)
	return ""


func _policy_item_price(item: Node, viewport_rect: Rect2) -> Variant:
	if not _policy_bool(item.get("active")):
		return null
	var buy: Node = item.find_child("Buy", true, false)
	if buy == null or not _policy_visible_on_screen(buy, viewport_rect):
		return null
	var text: String = _policy_display_text(buy, viewport_rect)
	if text.is_empty():
		return null
	return {"display": text, "dollars": text.replace("$", "").to_float()}


func _policy_shop_edit_state(scene: Node, viewport_rect: Rect2) -> Variant:
	var stats: Node = _policy_find(scene, "Stats&Items")
	if stats == null:
		return null
	var result: Dictionary = {"cash_display": null, "cash_dollars": null, "shop_items": [], "gear_slots": [], "clock_numbers": null, "papers": null}
	var money: Node = _policy_find(stats, "Money")
	var money_label: Node = _policy_find(money, "Label") if money != null else null
	if money_label != null and _policy_visible_on_screen(money_label, viewport_rect):
		var cash_text: String = _policy_text_from_control(money_label)
		result.cash_display = cash_text
		result.cash_dollars = cash_text.replace("$", "").to_float()
	var gear_slots: Node = _policy_find(stats, "Gears")
	if gear_slots != null:
		var equipped: Array = []
		_policy_collect_script_nodes(gear_slots, "/Objs/Gears/usable_gear.gd", equipped)
		for item in equipped:
			if _policy_visible_on_screen(item, viewport_rect):
				result.gear_slots.append({"slot": item.get_index(), "item": _policy_item_name(item), "description": _policy_visible_description(item, viewport_rect)})
	var shop: Node = scene.get_node_or_null("Shop")
	if shop != null:
		var shop_items: Array = []
		var gear_offers: Array = []
		var paper_boxes: Array = []
		_policy_collect_script_nodes(shop, "/Objs/Gears/gear.gd", gear_offers)
		_policy_collect_script_nodes(shop, "/Objs/Papers/box_of_papers.gd", paper_boxes)
		for item in gear_offers:
			if _policy_visible_on_screen(item, viewport_rect):
				shop_items.append({"kind": "gear", "item": _policy_item_name(item), "price": _policy_item_price(item, viewport_rect), "selected": _policy_bool(item.get("active")), "description": _policy_visible_description(item, viewport_rect)})
		for item in paper_boxes:
			if _policy_visible_on_screen(item, viewport_rect):
				shop_items.append({"kind": "paper_box", "item": "Box of Papers", "price": _policy_item_price(item, viewport_rect), "selected": _policy_bool(item.get("active")), "description": _policy_visible_description(item, viewport_rect)})
		result.shop_items = shop_items
	var edit: Node = _policy_find(scene, "ClockChanging")
	if edit != null and _policy_bool(edit.get("open")):
		var displayed_numbers: Array = []
		var number_nodes: Array = []
		_policy_collect_script_nodes(edit, "/changeable_clock_number.gd", number_nodes)
		for number in number_nodes:
			if _policy_visible_on_screen(number, viewport_rect):
				displayed_numbers.append({"value": int(number.get("val")), "selected": number.button_pressed, "id": str(number.get_path())})
		result.clock_numbers = displayed_numbers
		var visible_papers: Array = []
		var paper_nodes: Array = []
		_policy_collect_script_nodes(edit, "/Objs/Papers/paper.gd", paper_nodes)
		for paper in paper_nodes:
			if _policy_visible_on_screen(paper, viewport_rect):
				visible_papers.append({"item": _policy_item_name(paper), "selected": _policy_bool(paper.get("active")), "description": _policy_visible_description(paper, viewport_rect)})
		result.papers = visible_papers
	return result


func _policy_screen_phase(scene: Node, viewport_rect: Rect2, tutorial_state: Variant, input_blocked: bool) -> Dictionary:
	var game_node: Node = scene.get_node_or_null("Game")
	var shop: Node = scene.get_node_or_null("Shop")
	var money: Node = scene.get_node_or_null("Money")
	var edit: Node = scene.get_node_or_null("ClockChanging")
	var death: Node = scene.get_node_or_null("Death")
	var menu: Node = scene.get_node_or_null("Menu")
	var phase: String = "transition"
	var underlying: String = "transition"
	var pass_time: Node = game_node.get_node_or_null("PassTime") if game_node != null else null
	var clock_screen_visible: bool = _policy_visible_on_screen(pass_time, viewport_rect)
	if death != null and _policy_bool(death.get("open")) and _policy_screen_content_visible(death, viewport_rect):
		phase = "terminal"
		underlying = "terminal"
	elif edit != null and _policy_bool(edit.get("open")) and _policy_screen_content_visible(edit, viewport_rect):
		underlying = "clock_edit"
		phase = "number_selection"
		var numbers: Node = _policy_find(edit, "Numbers")
		if numbers != null:
			for number in numbers.get_children():
				if number is BaseButton and (number as BaseButton).button_pressed:
					phase = "paper_selection"
		var paper_nodes: Array = []
		_policy_collect_script_nodes(edit, "/Objs/Papers/paper.gd", paper_nodes)
		for paper in paper_nodes:
			if _policy_bool(paper.get("active")):
				phase = "paper_selection"
	elif money != null and _policy_bool(money.get("open")) and _policy_screen_content_visible(money, viewport_rect):
		phase = "payout"
		underlying = "payout"
	elif shop != null and _policy_bool(shop.get("open")) and _policy_screen_content_visible(shop, viewport_rect):
		phase = "shop"
		underlying = "shop"
	elif menu != null and _policy_screen_content_visible(menu, viewport_rect):
		phase = "menu"
		underlying = "menu"
	elif clock_screen_visible:
		underlying = "active_clock"
		var stats: Node = _policy_find(scene, "Stats&Items")
		var score: Node = _policy_find(stats, "RoundScore") if stats != null else null
		var current: Node = _policy_find(stats, "CurentScore") if stats != null else null
		if not _policy_clock_animation_settled(scene, score, current, game_node):
			phase = "score_animation"
		else:
			phase = "active_clock"
	if tutorial_state != null:
		if tutorial_state["kind"] == "dialogue":
			phase = "tutorial_dialogue"
		elif tutorial_state["kind"] == "callout":
			phase = "tutorial_callout"
	var settled: bool = !input_blocked
	var transition: Node = scene.get_node_or_null("Transition")
	if transition != null and transition is Control and (transition as Control).visible:
		if absf((transition as Control).position.y + 720.0) > 1.0:
			settled = false
	for panel in [game_node, shop, money, edit, death, menu]:
		var panel_open: Variant = panel.get("open") if panel != null else null
		if panel == game_node:
			if clock_screen_visible:
				panel_open = true
			else:
				continue
		if not _policy_screen_transition_settled(panel, viewport_rect, panel_open):
			settled = false
	var overlay: Node = _policy_find(scene, "Tutorial Overlay")
	if overlay != null and overlay.is_visible_in_tree():
		for child in overlay.get_children():
			if child is Control and child.name != "Overlay" and child.name != "Voice":
				var scale: Vector2 = (child as Control).scale
				if scale.x > 0.02 and scale.x < 0.98:
					settled = false
	return {"stage": phase, "underlying_screen": underlying, "transition_settled": settled}
